import math

def is_prime(n):
    # Negative and zero numbers are not considered primes
    if n <= 1:
        return False

    # Check for divisibility by 2, as it's the only even prime number
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # We only need to check up until the square root of n and from odd numbers after eliminating 2.
    for i in range(3, int(math.sqrt(n)) + 1, 2):  
        if n % i == 0:
            return False

    return True
